func:
const errorFlag = flow.get("errorFlag") || false;
if (!errorFlag) {
    flow.set("errorFlag", true)
};
msg.delay = 10000;  // 10 seconds between retry
return msg;

// get errorFlag
const errorFlag = flow.get('errorFlag') || false;

// if errorFlag is True, do nothing and set errorFlag to false
if (errorFlag) {
    flow.set('errorFlag', false)
    return null
} else {
    msg.topic = 'control'
    msg.payload = 'peek'
    return msg
}

// Combine the error message and the queueText

const errorMessage = msg.error.message;
const queueText = flow.get("queueText") || "Queue: 0";
const combinedMessage = `${queueText} - ${errorMessage}`
node.status({ fill: "red", shape: "ring", text: combinedMessage});

// Set the Flow status to the status message of the q-gate
const queueText = flow.get("queueText") || "Queue: 0";
node.status({ fill: "yellow", shape: "ring", text: queueText});

// Reset the trigger and set the delay to high value to avoid
// peeking the same message from the queue again,
// if the database is not responding within a few seconds

msg.reset = true;
return msg;

// Statische Basisdaten
flow.set('BASE_URL', 'http://dpn-svr-dl:5000');
flow.set('USERNAME', 'wunram');
flow.set('PASSWORD', 'iBhYkE67CG!D');
// Reset State
flow.set('RUN_INDEX', 0);
flow.set('RETRY_MAP', {});
flow.set('COOKIES', {});
// Gemeinsame Standardparameter
const common = { test_size: 0.2, cv_folds: 5, top_n_features: 80, enable_tracking: false, use_transfer_learning: false };
// Sechs Läufe: je Modelltyp mit/ohne GridSearch
const queue = [
 { name: 'lgbm_no_gs', description: 'LightGBM ohne GridSearch', parameters: { ...common, model_type: 'lightgbm', use_gridsearch: false, n_estimators: 100, max_depth: 5, learning_rate: 0.1 } },
 { name: 'lgbm_gs', description: 'LightGBM mit GridSearch', parameters: { ...common, model_type: 'lightgbm', use_gridsearch: true, n_estimators: 100, max_depth: 5, learning_rate: 0.1 } },
 { name: 'xgb_no_gs', description: 'XGBoost ohne GridSearch', parameters: { ...common, model_type: 'xgboost', use_gridsearch: false, n_estimators: 300, max_depth: 30, learning_rate: 0.1 } },
 { name: 'xgb_gs', description: 'XGBoost mit GridSearch', parameters: { ...common, model_type: 'xgboost', use_gridsearch: true, n_estimators: 300, max_depth: 30, learning_rate: 0.1 } },
 { name: 'rf_no_gs', description: 'RandomForest ohne GS', parameters: { ...common, model_type: 'random_forest', use_gridsearch: false, n_estimators: 300, max_depth: 30 } },
 { name: 'rf_gs', description: 'RandomForest mit GS', parameters: { ...common, model_type: 'random_forest', use_gridsearch: true, n_estimators: 300, max_depth: 30 } }
];
flow.set('CONFIG_QUEUE', queue);
// Weiter zu Auth-Status
return msg;

const BASE_URL = flow.get('BASE_URL');
msg.method = 'GET';
msg.url = BASE_URL + '/api/auth/status';
msg.headers = { 'Accept': 'application/json' };
msg.intent = 'auth-status';
return msg;

if (msg.responseCookies) {
 flow.set('COOKIES', msg.responseCookies);
}
return msg;

const BASE_URL = flow.get('BASE_URL');
const USERNAME = flow.get('USERNAME');
const PASSWORD = flow.get('PASSWORD');
msg.method = 'POST';
msg.url = BASE_URL + '/api/auth/login';
msg.headers = { 'Content-Type': 'application/json', 'Accept': 'application/json' };
msg.payload = { username: USERNAME, password: PASSWORD };
msg.intent = 'login';
return msg;

let queue = flow.get('CONFIG_QUEUE') || [];
let idx = flow.get('RUN_INDEX') || 0;
if (idx >= queue.length) {
 msg.done = true;
 return msg;
}
const current = queue[idx];
msg.currentConfig = current;
msg.runIndex = idx;
flow.set('RUN_INDEX', idx + 1);
return msg;

const BASE_URL = flow.get('BASE_URL');
const cfg = msg.currentConfig;
msg.method = 'POST';
msg.url = BASE_URL + '/api/config/save';
msg.headers = { 'Content-Type': 'application/json', 'Accept': 'application/json' };
msg.payload = { name: cfg.name, description: cfg.description, parameters: cfg.parameters };
msg.intent = 'save-config';
return msg;

let ids = flow.get('SAVED_CONFIG_IDS') || {};
if (msg.payload && msg.payload.id) {
 ids[msg.currentConfig?.name || ('run_' + (msg.runIndex||0))] = msg.payload.id;
 flow.set('SAVED_CONFIG_IDS', ids);
}
return msg;

const BASE_URL = flow.get('BASE_URL');
const cfg = msg.currentConfig;
msg.method = 'POST';
msg.url = BASE_URL + '/api/config/session';
msg.headers = { 'Content-Type': 'application/json', 'Accept': 'application/json' };
msg.payload = { name: cfg.name, parameters: cfg.parameters };
msg.intent = 'config-session';
return msg;

const BASE_URL = flow.get('BASE_URL');
msg.method = 'POST';
msg.url = BASE_URL + '/api/training/start';
msg.headers = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
msg.payload = {};
msg.intent = 'train-start';
return msg;

const BASE_URL = flow.get('BASE_URL');
msg.method = 'GET';
msg.url = BASE_URL + '/api/training/status/current';
msg.headers = { 'Accept': 'application/json' };
msg.intent = 'status';
return msg;

const p = msg.payload || {};
msg.trainingStatus = p.status || '';
return msg;

const idx = (flow.get('RUN_INDEX')||1) - 1; // aktuell gelaufener Index
let retryMap = flow.get('RETRY_MAP') || {};
const key = 'run_' + idx;
const count = retryMap[key] || 0;
if (count < 3) {
 retryMap[key] = count + 1;
 flow.set('RETRY_MAP', retryMap);
 // RUN_INDEX zurücksetzen, um dieselbe Config zu wiederholen
 flow.set('RUN_INDEX', idx);
 return msg;
} else {
 // Retry-Zähler zurücksetzen und weiter zur nächsten Config
 retryMap[key] = 0;
 flow.set('RETRY_MAP', retryMap);
 return { payload: 'skip' };
}

const BASE_URL = flow.get('BASE_URL');
msg.method = 'POST';
msg.url = BASE_URL + '/api/auth/logout';
msg.headers = { 'Accept': 'application/json' };
msg.intent = 'logout';
return msg;

